72	  "job title": "title",
73	  name: "name",
74	  business: "name",
75	  company: "name",
76	  "company name": "name",
77	  organization: "name",
78	  category: "category",
79	  industry: "category",
80	  type: "businessType",
81	  businesstype: "businessType",
82	  website: "website",
83	  url: "website",
84	  domain: "website",
85	  phone: "phone",
