275	// ---------------------------------------------------------------------------
276	// The ingest orchestrator
277	// ---------------------------------------------------------------------------
278	
279	export type ImportResult = {
280	  totalRows: number;
281	  inserted: number;
282	  updated: number;
283	  skippedDead: number;
284	  skippedDup: number;
285	  skippedInvalid: number;
286	  contactIds: string[];
287	};
288	
289	export type IngestOptions = {
290	  store: LeadStore;
291	  listId: string | null;
292	  batchId?: string | null;
293	  recordConsent?: boolean;
294	  consentSource?: string;
295	};
296	
297	/**
298	 * Ingest normalized-or-raw rows into the lead database, idempotently.
299	 *
300	 * For each row (see file header for the full guarantee set): validate → dedup
301	 * within the file → look up the existing contact → refuse dead/suppressed →
302	 * update-or-insert → add to the target list. Returns the batch tally.
303	 */
304	export async function ingestLeads(rows: LeadRow[], opts: IngestOptions): Promise<ImportResult> {
305	  const { store, listId, batchId = null, recordConsent = false, consentSource = "bulk import" } = opts;
306	  const result: ImportResult = {
307	    totalRows: rows.length,
308	    inserted: 0,
309	    updated: 0,
310	    skippedDead: 0,
311	    skippedDup: 0,
312	    skippedInvalid: 0,
313	    contactIds: [],
314	  };
315	
316	  const seen = new Set<string>(); // in-file dedup by normalized email
317	
318	  for (const raw of rows) {
319	    const lead = normalizeLeadRow(raw);
320	    if (!lead) {
321	      result.skippedInvalid++;
322	      continue;
323	    }
324	    if (seen.has(lead.email)) {
325	      result.skippedDup++;
326	      continue;
327	    }
328	    seen.add(lead.email);
329	
330	    const existing = await store.findContact(lead.email);
331	
332	    if (existing) {
333	      // NEVER resurrect a dead/suppressed contact.
334	      if (isDeadStatus(existing.emailStatus) || (await store.isSuppressed(lead.email))) {
335	        result.skippedDead++;
336	        continue;
337	      }
338	      // Update in place (fill blanks only) + re-add to the list. No duplicate row.
339	      await store.updateContact(
340	        existing.id,
341	        {
342	          fullName: existing.fullName ? undefined : lead.fullName || undefined,
343	          title: existing.title ? undefined : lead.title || undefined,
344	        },
345	        batchId,
346	      );
347	      if (listId) await store.addToList(existing.id, listId);
348	      result.updated++;
349	      result.contactIds.push(existing.id);
350	      continue;
351	    }
352	
353	    // Brand-new email: refuse if it's already globally suppressed (opted-out before
354	    // the contact row existed) — we never add a suppressed address.
355	    if (await store.isSuppressed(lead.email)) {
356	      result.skippedDead++;
357	      continue;
358	    }
359	
360	    const businessId = await store.createBusiness(lead.business, batchId);
361	    const contactId = await store.createContact(
362	      { businessId, email: lead.email, fullName: lead.fullName, title: lead.title },
363	      batchId,
364	    );
365	    if (listId) await store.addToList(contactId, listId);
366	    if (recordConsent) await store.recordConsent(contactId, consentSource, lead.sourceUrl || undefined);
367	    result.inserted++;
368	    result.contactIds.push(contactId);
369	  }
370	
371	  return result;
372	}
