1	// Cold Email Engine — LEAD-DATABASE hygiene core.
2	//
3	// PURE + unit-testable (no DB, no I/O), same discipline as compliance.ts. This is
4	// the single source of truth for the lead-database's health model:
5	//
6	//   * which email statuses are MAILABLE (may be added to a campaign),
7	//   * how an SMTP result classifies as a HARD (permanent 5xx) or SOFT (transient
8	//     4xx) bounce,
9	//   * how a bounce / complaint / unsubscribe transitions a contact's health
10	//     ("bounce → dead" pipeline), and
11	//   * an idempotent recompute of a contact's status from its aggregate event
12	//     counts (used by the reconciliation sweep).
13	//
14	// RESEARCH APPLIED (see docs/DOCUMENTATION.md for citations):
15	//   - Hard bounce (5xx) = permanent → suppress after ONE occurrence, dead forever.
16	//   - Soft bounce (4xx) = transient → retry; suppress only after N consecutive
17	//     failures (default 3). Over-aggressive soft suppression loses valid contacts.
18	//   - Spam complaint → suppress immediately (Gmail caps complaint rate at 0.3%,
19	//     target < 0.1%).
20	//   - Unsubscribe / "not interested" reply → treat as opt-out, suppress same-day.
21	//   - Merge suppression globally so a dead/opted-out address is never re-mailed by
22	//     ANY brand — and never resurrected on re-import.
23	
24	// ---------------------------------------------------------------------------
25	// Status model (string literals so this module never imports the Prisma client
26	// and stays importable in a DB-less test).
27	// ---------------------------------------------------------------------------
28	
29	export type EmailStatusValue =
30	  | "UNKNOWN"
31	  | "UNVERIFIED"
32	  | "VALID"
33	  | "RISKY"
34	  | "INVALID"
35	  | "HARD_BOUNCED"
36	  | "SOFT_BOUNCED"
37	  | "COMPLAINED"
38	  | "UNSUBSCRIBED"
39	  | "DEAD";
40	
41	/**
42	 * Statuses a contact may still be emailed at. UNKNOWN is legacy-equivalent to
43	 * UNVERIFIED. SOFT_BOUNCED stays mailable ON PURPOSE — a soft bounce is transient,
44	 * so the contact is retried until it crosses the dead threshold (then → DEAD).
45	 */
46	export const MAILABLE_STATUSES: readonly EmailStatusValue[] = [
47	  "UNKNOWN",
48	  "UNVERIFIED",
49	  "VALID",
50	  "RISKY",
51	  "SOFT_BOUNCED",
52	];
53	
54	/**
55	 * Terminal "do-not-contact" statuses. A contact here is excluded from every future
56	 * campaign and is NEVER resurrected by a re-import (see import.ts).
57	 */
58	export const DEAD_STATUSES: readonly EmailStatusValue[] = [
59	  "INVALID",
60	  "HARD_BOUNCED",
61	  "COMPLAINED",
62	  "UNSUBSCRIBED",
63	  "DEAD",
64	];
65	
66	/** Default number of soft (4xx) bounces before a contact is sunset to DEAD. */
67	export const DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD = 3;
68	
69	/** Is this status one we may still email? */
70	export function isMailableStatus(status: EmailStatusValue | string | null | undefined): boolean {
71	  return MAILABLE_STATUSES.includes((status ?? "UNVERIFIED") as EmailStatusValue);
72	}
73	
74	/** Is this status terminal (dead / suppressed)? */
75	export function isDeadStatus(status: EmailStatusValue | string | null | undefined): boolean {
76	  return DEAD_STATUSES.includes((status ?? "") as EmailStatusValue);
77	}
78	
79	/**
80	 * Final mailability of a contact: a mailable STATUS **and** not globally
81	 * suppressed. This is the one predicate campaign-build + preview consult.
82	 */
83	export function isMailable(input: { emailStatus: EmailStatusValue | string; suppressed?: boolean }): boolean {
84	  if (input.suppressed) return false;
85	  return isMailableStatus(input.emailStatus);
86	}
87	
88	// ---------------------------------------------------------------------------
89	// Bounce classification — 5xx permanent (HARD) vs 4xx transient (SOFT)
90	// ---------------------------------------------------------------------------
91	
92	export type BounceType = "HARD" | "SOFT";
93	
94	/**
95	 * Classify a bounce from an SMTP status. Accepts:
96	 *   - a numeric basic code (e.g. 550, 421),
97	 *   - a string basic code ("550"),
98	 *   - an enhanced DSN code ("5.1.1", "4.2.2"),
99	 *   - a raw DSN line beginning with the code.
100	 * Returns "HARD" for 5xx (permanent), "SOFT" for 4xx (transient), or null if the
101	 * code is not a 4/5xx failure (2xx/3xx or unparseable).
102	 */
103	export function classifyBounceCode(code: number | string | null | undefined): BounceType | null {
104	  if (code == null) return null;
105	  const s = String(code).trim();
106	  if (!s) return null;
107	  // First digit of the basic class. Handle "550", "5.1.1", "550 5.1.1 User unknown".
108	  const first = s[0];
109	  if (first === "5") return "HARD";
110	  if (first === "4") return "SOFT";
111	  const n = Number(s);
112	  if (Number.isFinite(n)) {
113	    if (n >= 500 && n < 600) return "HARD";
114	    if (n >= 400 && n < 500) return "SOFT";
115	  }
116	  return null;
117	}
118	
119	// ---------------------------------------------------------------------------
120	// Bounce / complaint / unsubscribe → status transition ("bounce → dead")
121	// ---------------------------------------------------------------------------
122	
123	export type HygieneEvent = "HARD_BOUNCE" | "SOFT_BOUNCE" | "COMPLAINT" | "UNSUBSCRIBE";
124	
125	export type SuppressReason = "BOUNCE" | "COMPLAINT" | "UNSUBSCRIBE";
126	
127	export type HygieneTransition = {
128	  /** The contact's new emailStatus. */
129	  emailStatus: EmailStatusValue;
130	  /** New absolute bounceCount (soft bounces accumulate; other events leave it). */
131	  bounceCount: number;
132	  /** True when this event moved the contact into a terminal/dead state. */
133	  dead: boolean;
134	  /** Human-readable reason to stamp on deadReason when `dead`. */
135	  deadReason: string;
136	  /** Whether to write a GLOBAL Suppression (never for a soft bounce below threshold). */
137	  suppress: boolean;
138	  /** Suppression reason when `suppress`. */
139	  suppressReason: SuppressReason | null;
140	  /** Whether to stamp lastBounceAt (bounce events only). */
141	  stampBounceAt: boolean;
142	};
143	
144	/**
145	 * Apply one hygiene event to a contact's current health. PURE — the caller
146	 * persists the returned fields and writes the suppression when `suppress`.
147	 *
148	 * Rules (research-backed):
149	 *   HARD_BOUNCE  → HARD_BOUNCED, dead, suppress(BOUNCE), immediately.
150	 *   COMPLAINT    → COMPLAINED,   dead, suppress(COMPLAINT).
151	 *   UNSUBSCRIBE  → UNSUBSCRIBED, dead, suppress(UNSUBSCRIBE).
152	 *   SOFT_BOUNCE  → bounceCount+1; if >= threshold → DEAD + suppress(BOUNCE),
153	 *                  else SOFT_BOUNCED (still mailable, no suppression).
154	 *
155	 * A contact ALREADY in a dead status is sticky: the event is a no-op transition
156	 * that re-asserts suppression (idempotent) and never resurrects or downgrades it.
157	 */
158	export function applyHygieneEvent(
159	  current: { emailStatus: EmailStatusValue | string; bounceCount?: number | null },
160	  event: HygieneEvent,
161	  opts: { softBounceDeadThreshold?: number; reason?: string } = {},
162	): HygieneTransition {
163	  const status = (current.emailStatus ?? "UNVERIFIED") as EmailStatusValue;
164	  const count = Math.max(0, current.bounceCount ?? 0);
165	  const threshold = clampThreshold(opts.softBounceDeadThreshold);
166	
167	  // Terminal is sticky — never resurrect. Re-assert suppression so a duplicate
168	  // event still guarantees the address is suppressed.
169	  if (isDeadStatus(status)) {
170	    return {
171	      emailStatus: status,
172	      bounceCount: count,
173	      dead: true,
174	      deadReason: "",
175	      suppress: status !== "INVALID", // INVALID predates suppression; don't force it
176	      suppressReason: status === "COMPLAINED" ? "COMPLAINT" : status === "UNSUBSCRIBED" ? "UNSUBSCRIBE" : "BOUNCE",
177	      stampBounceAt: false,
178	    };
179	  }
180	
181	  switch (event) {
182	    case "HARD_BOUNCE":
183	      return {
184	        emailStatus: "HARD_BOUNCED",
185	        bounceCount: count + 1,
186	        dead: true,
187	        deadReason: opts.reason || "Hard bounce — permanent 5xx delivery failure (invalid address)",
188	        suppress: true,
189	        suppressReason: "BOUNCE",
190	        stampBounceAt: true,
191	      };
192	    case "COMPLAINT":
193	      return {
194	        emailStatus: "COMPLAINED",
195	        bounceCount: count,
196	        dead: true,
197	        deadReason: opts.reason || "Spam complaint / feedback-loop report",
198	        suppress: true,
199	        suppressReason: "COMPLAINT",
200	        stampBounceAt: false,
201	      };
202	    case "UNSUBSCRIBE":
203	      return {
204	        emailStatus: "UNSUBSCRIBED",
205	        bounceCount: count,
206	        dead: true,
207	        deadReason: opts.reason || "Unsubscribed / opted out",
208	        suppress: true,
209	        suppressReason: "UNSUBSCRIBE",
210	        stampBounceAt: false,
211	      };
212	    case "SOFT_BOUNCE": {
213	      const next = count + 1;
214	      if (next >= threshold) {
215	        return {
216	          emailStatus: "DEAD",
217	          bounceCount: next,
218	          dead: true,
219	          deadReason:
220	            opts.reason || `Sunset after ${next} transient (4xx) soft bounces (threshold ${threshold})`,
221	          suppress: true,
222	          suppressReason: "BOUNCE",
223	          stampBounceAt: true,
224	        };
225	      }
226	      return {
227	        emailStatus: "SOFT_BOUNCED",
228	        bounceCount: next,
229	        dead: false,
230	        deadReason: "",
231	        suppress: false,
232	        suppressReason: null,
233	        stampBounceAt: true,
234	      };
235	    }
236	  }
237	}
238	
239	function clampThreshold(v: number | null | undefined): number {
240	  const n = Number(v);
241	  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD;
242	}
243	
244	// ---------------------------------------------------------------------------
245	// Idempotent recompute from aggregate event counts (reconciliation sweep)
246	// ---------------------------------------------------------------------------
247	
248	export type EventCounts = {
249	  hardBounce?: number;
250	  softBounce?: number;
251	  complaint?: number;
252	  unsubscribe?: number;
253	};
254	
255	export type ReconcileResult = {
256	  emailStatus: EmailStatusValue;
257	  bounceCount: number;
258	  dead: boolean;
259	  deadReason: string;
260	  suppress: boolean;
261	  suppressReason: SuppressReason | null;
262	  /** True when the recompute actually changes the stored status. */
263	  changed: boolean;
264	};
265	
266	/**
267	 * Recompute a contact's health from the FULL aggregate of its lifetime events.
268	 * Deterministic + idempotent: running it twice yields the same result, so it is
269	 * safe to re-run in a sweep. Severity order: complaint > unsubscribe > hard bounce
270	 * > soft-bounce sunset. A contact with no adverse events keeps its current status
271	 * (we never downgrade a VALID/RISKY address here — that's verification's job).
272	 */
273	export function reconcileEmailStatus(
274	  counts: EventCounts,
275	  current: { emailStatus: EmailStatusValue | string; bounceCount?: number | null },
276	  softBounceDeadThreshold: number = DEFAULT_SOFT_BOUNCE_DEAD_THRESHOLD,
277	): ReconcileResult {
278	  const status = (current.emailStatus ?? "UNVERIFIED") as EmailStatusValue;
279	  const threshold = clampThreshold(softBounceDeadThreshold);
280	  const hard = Math.max(0, counts.hardBounce ?? 0);
281	  const soft = Math.max(0, counts.softBounce ?? 0);
282	  const complaint = Math.max(0, counts.complaint ?? 0);
283	  const unsub = Math.max(0, counts.unsubscribe ?? 0);
284	
285	  let next: EmailStatusValue = status;
286	  let dead = false;
287	  let deadReason = "";
288	  let suppress = false;
289	  let suppressReason: SuppressReason | null = null;
290	
291	  if (complaint > 0) {
292	    next = "COMPLAINED";
293	    dead = true;
294	    deadReason = "Spam complaint / feedback-loop report";
295	    suppress = true;
296	    suppressReason = "COMPLAINT";
297	  } else if (unsub > 0) {
298	    next = "UNSUBSCRIBED";
299	    dead = true;
300	    deadReason = "Unsubscribed / opted out";
301	    suppress = true;
302	    suppressReason = "UNSUBSCRIBE";
303	  } else if (hard > 0) {
304	    next = "HARD_BOUNCED";
305	    dead = true;
306	    deadReason = "Hard bounce — permanent 5xx delivery failure (invalid address)";
307	    suppress = true;
308	    suppressReason = "BOUNCE";
309	  } else if (soft >= threshold) {
310	    next = "DEAD";
311	    dead = true;
312	    deadReason = `Sunset after ${soft} transient (4xx) soft bounces (threshold ${threshold})`;
313	    suppress = true;
314	    suppressReason = "BOUNCE";
315	  } else if (soft > 0 && isMailableStatus(status)) {
316	    next = "SOFT_BOUNCED";
317	  }
318	
319	  // Never downgrade a contact that is already terminal to something "less dead".
320	  if (isDeadStatus(status) && !isDeadStatus(next)) {
321	    next = status;
322	    dead = true;
323	  }
324	
325	  return {
326	    emailStatus: next,
327	    bounceCount: soft,
328	    dead,
329	    deadReason,
330	    suppress,
331	    suppressReason,
332	    changed: next !== status,
333	  };
334	}
335	
336	// ---------------------------------------------------------------------------
337	// Presentation helper — the contact status badge shown across the admin UI
338	// ---------------------------------------------------------------------------
339	
340	/**
341	 * Roll a set of contacts up into a lead-health summary for a list / segment card:
342	 * how many are sendable (mailable), dead, already-emailed, and replied.
343	 */
344	export type LeadHealthSummary = { total: number; sendable: number; dead: number; emailed: number; replied: number };
345	
346	export function summarizeLeadHealth(
347	  contacts: { emailStatus: EmailStatusValue | string; timesEmailed?: number | null; repliedAt?: Date | string | null }[],
348	): LeadHealthSummary {
349	  const s: LeadHealthSummary = { total: contacts.length, sendable: 0, dead: 0, emailed: 0, replied: 0 };
350	  for (const c of contacts) {
351	    if (isMailableStatus(c.emailStatus)) s.sendable++;
352	    else s.dead++;
353	    if ((c.timesEmailed ?? 0) > 0) s.emailed++;
354	    if (c.repliedAt) s.replied++;
355	  }
356	  return s;
357	}
358	
359	export type StatusBadge = { label: string; tone: "green" | "red" | "amber" | "slate" | "brand" };
360	
361	/**
362	 * The single status badge for a contact, folding address-health + engagement into
363	 * one label: Dead / Bounced / Unsubscribed / Replied / Emailed / Valid / New.
364	 */
365	export function contactStatusBadge(c: {
366	  emailStatus: EmailStatusValue | string;
367	  timesEmailed?: number | null;
368	  repliedAt?: Date | string | null;
369	}): StatusBadge {
370	  const s = (c.emailStatus ?? "UNVERIFIED") as EmailStatusValue;
371	  if (s === "HARD_BOUNCED" || s === "DEAD" || s === "INVALID" || s === "SOFT_BOUNCED") {
372	    return { label: s === "SOFT_BOUNCED" ? "Bounced (soft)" : "Bounced/Dead", tone: "red" };
373	  }
374	  if (s === "COMPLAINED") return { label: "Complained", tone: "red" };
375	  if (s === "UNSUBSCRIBED") return { label: "Unsubscribed", tone: "amber" };
376	  if (c.repliedAt) return { label: "Replied", tone: "green" };
377	  if ((c.timesEmailed ?? 0) > 0) return { label: "Emailed", tone: "brand" };
378	  if (s === "VALID") return { label: "Valid", tone: "green" };
379	  return { label: "New", tone: "slate" };
380	}
