502	/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
503	async function maybeCompleteCampaign(campaignId: string): Promise<void> {
504	  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
505	  if (remaining > 0) return;
506	  const any = await db.coldSend.count({ where: { campaignId } });
507	  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
508	  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
509	}
