511	/**
512	 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
513	 * keeps everything below inert until a human enables sending on prod.
514	 */
515	export async function coldEmailSendSweep(): Promise<void> {
516	  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
517	  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;
518	
519	  let campaigns: CampaignForSend[];
520	  try {
521	    campaigns = await db.coldCampaign.findMany({
522	      where: { status: "SENDING" },
523	      select: {
524	        id: true,
525	        brandId: true,
526	        listId: true,
527	        launchedAt: true,
528	        sendWindowStart: true,
529	        sendWindowEnd: true,
530	        timezone: true,
531	      },
532	    });
533	  } catch {
534	    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
535	    return;
536	  }
537	  if (campaigns.length === 0) return;
538	
539	  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
540	  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
541	  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
542	  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
543	  const now = new Date();
544	
545	  let transport: MailTransport;
546	  try {
547	    transport = await getTransport("nxeon-smtp");
548	  } catch (err) {
549	    await logEvent("error", "coldemail.transport.init", { message: String(err) });
550	    return;
551	  }
552	
553	  let budget = MAX_SENDS_PER_SWEEP;
554	  for (const campaign of campaigns) {
555	    if (budget <= 0) break;
556	
557	    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
558	    if (!brand) continue;
559	
560	    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
561	    const eligibility = evaluateSendEligibility(brand, protectedSet);
562	    if (!eligibility.eligible) {
563	      await logEvent("warn", "coldemail.send.brand_blocked", {
564	        campaignId: campaign.id,
565	        brandId: brand.id,
566	        reasons: eligibility.reasons,
567	      });
568	      continue;
569	    }
570	
571	    const identity: SendIdentity = {
572	      id: brand.id,
573	      name: brand.name,
574	      fromName: brand.fromName,
575	      fromEmail: brand.fromEmail,
576	      replyTo: brand.replyTo,
577	      sendingDomain: brand.sendingDomain,
578	      physicalPostalAddress: brand.physicalPostalAddress,
579	    };
580	
581	    try {
582	      await scheduleCampaignSends(campaign);
583	      const sent = await processDueSends(campaign, identity, {
584	        now,
585	        transport,
586	        ceiling,
587	        warmupEnabled,
588	        footerDisclosure,
589	        budget,
590	      });
591	      budget -= sent;
592	      await maybeCompleteCampaign(campaign.id);
593	    } catch (err) {
594	      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
595	    }
596	  }
597	}
