47	// ---------------------------------------------------------------------------
48	// CSV parsing (server-side, no dependency). Handles quoted fields, embedded
49	// commas/newlines, and doubled quotes. First non-empty row is the header.
50	// ---------------------------------------------------------------------------
51	
52	function parseCsv(text: string): { headers: string[]; rows: string[][] } {
53	  const records: string[][] = [];
54	  let field = "";
55	  let row: string[] = [];
56	  let inQuotes = false;
57	  const src = text.replace(/\r\n?/g, "\n");
58	
59	  for (let i = 0; i < src.length; i++) {
60	    const c = src[i];
61	    if (inQuotes) {
62	      if (c === '"') {
63	        if (src[i + 1] === '"') {
64	          field += '"';
65	          i++;
66	        } else {
67	          inQuotes = false;
68	        }
69	      } else {
70	        field += c;
71	      }
72	    } else if (c === '"') {
73	      inQuotes = true;
74	    } else if (c === ",") {
75	      row.push(field);
76	      field = "";
77	    } else if (c === "\n") {
78	      row.push(field);
79	      records.push(row);
80	      row = [];
81	      field = "";
82	    } else {
83	      field += c;
84	    }
85	  }
86	  // Flush trailing field/row.
87	  if (field.length > 0 || row.length > 0) {
88	    row.push(field);
89	    records.push(row);
90	  }
91	
92	  const nonEmpty = records.filter((r) => r.some((v) => v.trim() !== ""));
93	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
94	  const headers = nonEmpty[0].map((h) => h.trim().toLowerCase());
95	  return { headers, rows: nonEmpty.slice(1) };
96	}
