833	export async function addSuppression(_prev: ActionState, formData: FormData): Promise<ActionState> {
834	  await requireArea("platform");
835	  const rawValue = String(formData.get("value") ?? "").trim().toLowerCase();
836	  const kind = String(formData.get("kind") ?? "email"); // "email" | "domain"
