838	  const reason = (SUPPRESSION_REASONS as readonly string[]).includes(reasonRaw)
839	    ? (reasonRaw as (typeof SUPPRESSION_REASONS)[number])
840	    : "MANUAL";
841	  if (!rawValue) return { error: "Enter an email address or domain." };
842	
843	  const isEmail = kind === "email";
844	  if (isEmail && !emailSchema.safeParse(rawValue).success) return { error: "Enter a valid email address." };
845	  if (!isEmail && !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(rawValue)) return { error: "Enter a valid domain." };
846	
847	  const where = isEmail
848	    ? { scope: "GLOBAL" as const, email: rawValue }
849	    : { scope: "GLOBAL" as const, domain: rawValue };
850	  const existing = await db.suppression.findFirst({ where, select: { id: true } });
851	  if (!existing) {
852	    await db.suppression.create({
853	      data: isEmail
854	        ? { scope: "GLOBAL", email: rawValue, reason }
855	        : { scope: "GLOBAL", domain: rawValue, reason },
856	    });
