871	/** Bulk import suppression entries (one email or domain per line, or CSV). */
872	export async function importSuppressionCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
873	  await requireArea("platform");
874	  const text = String(formData.get("csv") ?? "");
875	  if (!text.trim()) return { error: "Paste some addresses or domains first." };
876	
877	  const tokens = text
878	    .split(/[\n,;\s]+/)
879	    .map((t) => t.trim().toLowerCase())
880	    .filter(Boolean);
881	
882	  let added = 0;
883	  let skipped = 0;
884	  for (const t of tokens) {
885	    const isEmail = t.includes("@");
886	    const valid = isEmail ? emailSchema.safeParse(t).success : /^[a-z0-9.-]+\.[a-z]{2,}$/.test(t);
887	    if (!valid) {
888	      skipped++;
889	      continue;
890	    }
891	    const where = isEmail ? { scope: "GLOBAL" as const, email: t } : { scope: "GLOBAL" as const, domain: t };
892	    const existing = await db.suppression.findFirst({ where, select: { id: true } });
893	    if (existing) {
894	      skipped++;
895	      continue;
896	    }
897	    await db.suppression.create({
898	      data: isEmail
899	        ? { scope: "GLOBAL", email: t, reason: "MANUAL" }
900	        : { scope: "GLOBAL", domain: t, reason: "MANUAL" },
901	    });
902	    added++;
903	  }
