1375	/**
1376	 * Record a manual deliverability signal (reply / positive reply / delivered /
1377	 * hard-bounce / soft-bounce / complaint) into the analytics spine. Hard-bounce +
1378	 * complaint additionally suppress the address via the existing feedback path.
1379	 */
1380	export async function recordDeliverabilitySignal(_prev: ActionState, formData: FormData): Promise<ActionState> {
1381	  await requireArea("platform");
1382	  const type = pick(
1383	    ["REPLY", "POSITIVE_REPLY", "DELIVERED", "HARD_BOUNCE", "SOFT_BOUNCE", "COMPLAINT"] as const,
1384	    formData.get("type"),
1385	    "REPLY",
1386	  );
1387	  const email = normalizeEmail(String(formData.get("email") ?? ""));
1388	  if (email && !emailSchema.safeParse(email).success) return { error: "Enter a valid email or leave it blank." };
1389	
1390	  // Resolve the address to its latest send for attribution (best effort).
1391	  let sendId: string | null = null;
1392	  let campaignId: string | null = null;
1393	  let inboxId: string | null = null;
1394	  let sendingDomainId: string | null = null;
1395	  if (email) {
1396	    const contact = await db.contact.findUnique({ where: { email }, select: { id: true } });
1397	    if (contact) {
1398	      const last = await db.coldSend.findFirst({
1399	        where: { contactId: contact.id },
1400	        orderBy: { createdAt: "desc" },
1401	        select: { id: true, campaignId: true, inboxId: true, inbox: { select: { sendingDomainId: true } } },
1402	      });
1403	      if (last) {
1404	        sendId = last.id;
1405	        campaignId = last.campaignId;
1406	        inboxId = last.inboxId;
1407	        sendingDomainId = last.inbox?.sendingDomainId ?? null;
1408	      }
1409	    }
1410	  }
1411	
1412	  await db.deliverabilityEvent
1413	    .create({ data: { type, sendId, campaignId, inboxId, sendingDomainId, meta: "manual admin entry" } })
1414	    .catch(() => null);
1415	
1416	  // A bounce or complaint must run the lead-DB hygiene pipeline (hard/complaint =>
1417	  // suppress + dead; soft => increment bounceCount, sunset to DEAD past threshold).
1418	  if (email && (type === "HARD_BOUNCE" || type === "SOFT_BOUNCE" || type === "COMPLAINT")) {
1419	    await recordFeedback(email, type, { note: "manual deliverability entry" });
1420	  }
1421	  revalidatePath("/admin/coldemail/analytics");
1422	  return { ok: true, error: `Recorded ${type.replace(/_/g, " ").toLowerCase()}.` };
1423	}
