93	/**
94	 * Verify the token and record a GLOBAL suppression. Idempotent and silent about
95	 * whether the contact exists. Returns true when the request was well-formed.
96	 */
97	async function applyUnsubscribe(token: string | null): Promise<boolean> {
98	  const claims = verifyUnsubscribeToken(token);
99	  if (!claims) return false;
100	
101	  // Resolve the contact's email from the signed contactId. If the contact is
102	  // gone we still succeed (nothing to suppress, but the request was valid).
103	  const contact = await db.contact.findUnique({
104	    where: { id: claims.contactId },
105	    select: { email: true },
106	  });
107	  const email = (contact?.email ?? "").trim().toLowerCase();
108	  if (!email) return true;
109	
110	  // Idempotent: only insert if no GLOBAL row for this address exists yet.
111	  const existing = await db.suppression.findFirst({
112	    where: { email, scope: "GLOBAL" },
113	    select: { id: true },
114	  });
115	  if (!existing) {
116	    await db.suppression.create({
117	      data: { email, scope: "GLOBAL", reason: "UNSUBSCRIBE" },
118	    });
119	  }
120	  return true;
121	}
122	
123	export async function GET(req: Request) {
124	  const token = new URL(req.url).searchParams.get("token");
125	  if (!verifyUnsubscribeToken(token)) {
126	    return page("Invalid link", "This unsubscribe link is invalid or has expired.", 400);
127	  }
128	  return confirmPage(token!);
129	}
130	
131	export async function POST(req: Request) {
132	  // Token may arrive in the query string (RFC 8058 one-click) or the form body.
133	  let token = new URL(req.url).searchParams.get("token");
134	  if (!token) {
135	    try {
136	      const form = await req.formData();
137	      token = (form.get("token") as string | null) ?? null;
138	    } catch {
139	      /* no body */
140	    }
141	  }
142	
143	  const ok = await applyUnsubscribe(token);
144	  if (!ok) {
145	    return page("Invalid link", "This unsubscribe link is invalid or has expired.", 400);
146	  }
147	  return page("You're unsubscribed", "You will no longer receive these emails. You can close this page.");
148	}
